import assert from 'node:assert/strict';
import {DialogueRenderer,dialogueRenderer} from '../src/js/ui/DialogueRenderer.js';
import {ToyRoomStory} from '../src/js/toy-room/ToyRoomStory.js';
for(const [width,height] of [[960,540],[390,844],[844,390]]){
 const draws=[],portraits=[];const ctx=new Proxy({measureText:text=>({width:text.length*6}),roundRect:(...args)=>draws.push(args),createLinearGradient:()=>({addColorStop(){}})},{get:(obj,key)=>key in obj?obj[key]:()=>{},set:(obj,key,value)=>(obj[key]=value,true)});
 const renderer=new DialogueRenderer();renderer.drawPortrait=(_ctx,speaker)=>portraits.push(speaker);
 renderer.renderDialogue(ctx,{width,height},{speaker:'baby',speakerName:'MENINA',text:'Estamos vendo os mesmos brinquedos de novo.'});
 assert.deepEqual(portraits,['baby'],'Retrato da interlocutora aparece.');assert.ok(draws[0][1]>height/2,'Caixa fica junto da borda inferior.');assert.ok(draws[0][0]>=0&&draws[0][0]+draws[0][2]<=width,'Caixa cabe na largura.');
 renderer.renderCutsceneDialogue(ctx,{width,height},{cutsceneActive:true,cutsceneStep:2});assert.equal(portraits.at(-1),'baby','A primeira fase mantém seu retrato.');
}
const story=Object.create(ToyRoomStory.prototype);story.room={assets:{}};
const original=dialogueRenderer.renderDialogue,beats=[];dialogueRenderer.renderDialogue=(_ctx,_canvas,beat)=>beats.push(beat);
try{
 for(const [elapsed,speaker]of [[0,'fairy'],[120,'baby']]){
  story.state={returnDialogueElapsed:elapsed,investigationStage:'COLLECTING'};const before=JSON.stringify(story.state);story.renderNarrative({},{});assert.equal(beats.at(-1).speaker,speaker);assert.equal(JSON.stringify(story.state),before,'Render não altera narrativa persistida.');
 }
 for(const [elapsed,speaker]of [[0,'fairy'],[240,'baby']]){
  story.state={returnDialogueElapsed:-1,investigationStage:'INVESTIGATION',investigationElapsed:elapsed};story.renderNarrative({},{});assert.equal(beats.at(-1).speaker,speaker);
 }
 assert.ok(beats.every(beat=>beat.advancePrompt===undefined),'Falas temporizadas não pedem uma ação inexistente.');
}finally{dialogueRenderer.renderDialogue=original;}
console.log('APROVADO: caixa compartilhada, retratos corretos, limites responsivos, primeira fase e estado narrativo preservados.');
